<?php
namespace App\Domain\ApiHub;use App\Domain\ApiHub\Models\TenantApiIdempotencyRecord;use Illuminate\Support\Facades\DB;
final class ApiIdempotencyService{public function execute(int$tenant,int$client,string$endpoint,string$key,array$input,callable$callback):array{$fingerprint=hash('sha256',json_encode($this->sort($input),JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE));return DB::transaction(function()use($tenant,$client,$endpoint,$key,$fingerprint,$callback){$record=TenantApiIdempotencyRecord::where(['api_client_id'=>$client,'endpoint_code'=>$endpoint,'idempotency_key'=>$key])->lockForUpdate()->first();if($record){if(!hash_equals($record->request_fingerprint,$fingerprint))return['status'=>409,'body'=>['error'=>['code'=>'IDEMPOTENCY_CONFLICT','message'=>'La clave ya fue usada con una solicitud diferente.']],'replay'=>true];if($record->response_status)return['status'=>$record->response_status,'body'=>$record->response_body,'replay'=>true];}$record??=TenantApiIdempotencyRecord::create(['tenant_id'=>$tenant,'api_client_id'=>$client,'endpoint_code'=>$endpoint,'idempotency_key'=>$key,'request_fingerprint'=>$fingerprint,'expires_at'=>now()->addDay()]);$result=$callback();$record->update(['response_status'=>$result['status'],'response_body'=>$result['body']]);return$result+['replay'=>false];});}private function sort(array$value):array{ksort($value);foreach($value as$k=>$v)if(is_array($v))$value[$k]=$this->sort($v);return$value;}}
